"""Recall: answer-evidence for a question in plain code, before any model call.

The ladder: strip the question to keywords -> score every index entry WITHOUT
opening the files it points to -> open only the best file -> keep only the
paragraphs that match -> follow one pointer if those paragraphs miss most of
the keywords. Prints the evidence with file paths and line numbers; the model
answers from that in one go.

Index sources (Mac only):
  - Tier A:    ~/.claude/projects/-Users-kristinarash*/memory/MEMORY.md lines
  - Knowledge: ~/.claude/claude-memory-compiler/knowledge/index.md rows
  - Vault:     ~/SecondBrain notes, by file name + frontmatter + first heading
global-memory/USER.md and MEMORY.md are skipped: every session loads them.

Usage:
    python3 ~/.claude/scripts/recall.py "why did cloud-push fail on Drive"
    python3 ~/.claude/scripts/recall.py "..." --deep     # also run memsearch (slow: ~1 min)
    python3 ~/.claude/scripts/recall.py "..." --top 5    # show more candidates

Exit 0 = evidence printed, 1 = no index match (it prints the memsearch command).
"""
import argparse
import glob
import math
import os
import re
import subprocess
import sys

HOME = os.path.expanduser("~")
TIER_A = os.path.join(HOME, ".claude/projects/-Users-kristinarash*/memory/MEMORY.md")
KNOWLEDGE = os.path.join(HOME, ".claude/claude-memory-compiler/knowledge")
VAULT = os.path.join(HOME, "SecondBrain")
VAULT_SKIP = {".obsidian", ".trash", "Archive", "Templates", ".git"}
BUDGET = 1800  # evidence chars per file; a whole paragraph is never cut

STOP = set("""a about after again all also an and any are as at be been before being both
but by can could did do does doing done for from had has have how i if in into is it its
me my no not of on or our out over should so than that the their them then there these they
this those to up us was we were what when where which while who why will with would you your
again get got let make made many much more most now one only other same some such too very
just like each every first two three four""".split())


def stem(w):
    """Crude suffix strip so 'scanned' meets 'scan' and 'pages' meets 'page'."""
    for suf in ("ing", "ed", "es", "s"):
        if len(w) > len(suf) + 3 and w.endswith(suf):
            w = w[: -len(suf)]
            break
    if len(w) > 3 and w[-1] == w[-2] and w[-1] not in "aeiouls":
        w = w[:-1]
    return w


def tokens(text):
    return [stem(t) for t in re.findall(r"[a-z0-9]+", text.lower())]


def keywords(question):
    seen = []
    for t in tokens(question):
        if t not in STOP and len(t) > 1 and t not in seen:
            seen.append(t)
    return seen


# ---- index entries: (title, description, path) -------------------------------

def tier_a_entries(pattern=TIER_A):
    out = []
    for idx in glob.glob(pattern):
        base = os.path.dirname(idx)
        for line in open(idx, encoding="utf-8", errors="replace"):
            m = re.match(r"\s*-\s*\[([^\]]+)\]\(([^)]+)\)\s*[—-]*\s*(.*)", line)
            if m:
                title, rel, desc = m.groups()
                out.append((f"{title} {rel[:-3]}", desc, os.path.join(base, rel)))
    return out


def knowledge_entries(root=KNOWLEDGE):
    out, idx = [], os.path.join(root, "index.md")
    if not os.path.exists(idx):
        return out
    for line in open(idx, encoding="utf-8", errors="replace"):
        m = re.match(r"\|\s*\[\[([^\]]+)\]\]\s*\|([^|]*)\|", line)
        if m:
            rel, desc = m.groups()
            out.append((rel.split("/")[-1], desc, os.path.join(root, rel + ".md")))
    return out


def vault_head(path):
    """Frontmatter tags/aliases + first heading + first quote: the note's own catalogue line."""
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            head = fh.read(1500)
    except OSError:
        return ""
    keep = re.findall(r"^(?:tags|aliases|domain|description|title):.*$", head, re.M)
    keep += re.findall(r"^#\s+.*$", head, re.M)[:1] + re.findall(r"^>\s+.*$", head, re.M)[:1]
    return " ".join(keep)


def vault_entries(root=VAULT):
    out = []
    for dirpath, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d not in VAULT_SKIP]
        for f in files:
            if f.endswith(".md"):
                p = os.path.join(dirpath, f)
                out.append((f[:-3], vault_head(p), p))
    return out


def rank(kws, entries):
    """IDF-weighted keyword hits; a title hit counts double. Never opens the target."""
    docs = [(set(tokens(t)), set(tokens(d))) for t, d, _ in entries]
    n = len(docs) or 1
    idf = {k: math.log(1 + n / (1 + sum(1 for t, d in docs if k in t or k in d))) for k in kws}
    scored = []
    for (t, d), e in zip(docs, entries):
        s = sum(idf[k] * (2 if k in t else 1) for k in kws if k in t or k in d)
        hits = sum(1 for k in kws if k in t or k in d)
        if s:
            scored.append((s, hits, e))
    scored.sort(key=lambda x: (-x[0], -x[1]))
    return scored, idf


# ---- inside the one chosen file --------------------------------------------

def paragraphs(path):
    """(first line no, heading, text) per blank-line block, frontmatter dropped except description."""
    lines = open(path, encoding="utf-8", errors="replace").read().split("\n")
    out, start, heading, buf = [], 0, "", []
    i = 0
    if lines and lines[0].strip() == "---":
        for j in range(1, len(lines)):
            if lines[j].strip() == "---":
                desc = [l for l in lines[1:j] if l.startswith("description:")]
                if desc:
                    out.append((2, "", desc[0]))
                i = j + 1
                break
    for n in range(i, len(lines) + 1):
        line = lines[n] if n < len(lines) else ""
        if line.strip() == "" or n == len(lines):
            if buf:
                out.append((start + 1, heading, "\n".join(buf)))
                buf = []
            continue
        if line.startswith("#"):
            if buf:
                out.append((start + 1, heading, "\n".join(buf)))
                buf = []
            heading = line.lstrip("#").strip()
            continue
        if not buf:
            start = n
        buf.append(line)
    return out


def best_paragraphs(path, kws, idf, k=3):
    paras = paragraphs(path)
    scored = []
    for pos, (ln, head, text) in enumerate(paras):
        toks = set(tokens(head + " " + text))
        s = sum(idf.get(w, 1) for w in kws if w in toks)
        if s:
            scored.append((s, pos, ln, head, text, {w for w in kws if w in toks}))
    scored.sort(key=lambda x: -x[0])
    chosen, used = [], 0
    for item in scored[:k]:
        if chosen and used + len(item[4]) > BUDGET:
            continue
        chosen.append(item)
        used += len(item[4])
    chosen.sort(key=lambda x: x[1])  # back to document order
    return chosen


def pointers(text, from_path):
    """Resolvable [[name]] links and backticked .md paths, in order of appearance."""
    found = []
    for name in re.findall(r"\[\[([^\]|#]+)", text):
        name = name.strip()
        for cand in (os.path.join(os.path.dirname(from_path), name + ".md"),
                     os.path.join(os.path.dirname(from_path), "project_" + name + ".md"),
                     os.path.join(KNOWLEDGE, name + ".md")):
            if os.path.exists(cand):
                found.append(cand)
                break
        else:
            hits = glob.glob(os.path.join(VAULT, "**", name + ".md"), recursive=True)
            if hits:
                found.append(hits[0])
    for p in re.findall(r"`(~?/[^`\s]+\.md)`", text):
        p = os.path.expanduser(p)
        if os.path.exists(p):
            found.append(p)
    return [p for p in dict.fromkeys(found) if os.path.abspath(p) != os.path.abspath(from_path)]


def gather(question, entries, top=3):
    """Returns (kws, ranked, evidence) where evidence is [(path, [paragraph tuples])]."""
    kws = keywords(question)
    ranked, idf = rank(kws, entries)
    if not ranked:
        return kws, ranked, []
    path = ranked[0][2][2]
    if not os.path.exists(path):
        return kws, ranked, []
    chosen = best_paragraphs(path, kws, idf)
    evidence = [(path, chosen)]
    covered = set().union(*(c[5] for c in chosen)) if chosen else set()
    # One hop, gated: only when this file misses at least half the keywords.
    if len(covered) * 2 < len(kws):
        text = "\n".join(c[4] for c in chosen) or open(path, encoding="utf-8", errors="replace").read()
        for target in pointers(text, path)[:1]:
            extra = best_paragraphs(target, kws, idf)
            if extra and set().union(*(c[5] for c in extra)) - covered:
                evidence.append((target, extra))
    return kws, ranked, evidence


def short(p):
    return p.replace(HOME, "~")


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("question")
    ap.add_argument("--top", type=int, default=3, help="candidates to list")
    ap.add_argument("--deep", action="store_true", help="also run memsearch (slow)")
    a = ap.parse_args(argv)

    entries = tier_a_entries() + knowledge_entries() + vault_entries()
    kws, ranked, evidence = gather(a.question, entries)
    memsearch = f'memsearch search "{a.question}" --top-k 5'

    print(f"# recall: {a.question}")
    print(f"keywords: {' '.join(kws)}")
    print("candidates (not opened):")
    for s, hits, (title, _, path) in ranked[: a.top]:
        print(f"  {s:5.1f}  {hits}/{len(kws)}  {short(path)}")
    # shortcut: 2 keyword hits is the noise floor on ~3k entries; raise it if junk files win.
    if not evidence or not evidence[0][1] or ranked[0][1] < min(2, len(kws)):
        print(f"\nNO INDEX MATCH. Deeper (about 1 min): {memsearch}")
        if a.deep:
            print(subprocess.run(memsearch, shell=True, capture_output=True, text=True).stdout)
        return 1
    for path, chosen in evidence:
        print(f"\n## {short(path)}")
        for _, _, ln, head, text, _ in chosen:
            print(f"\n[line {ln}{' · ' + head if head else ''}]\n{text}")
    if a.deep:
        print("\n## memsearch\n" + subprocess.run(memsearch, shell=True, capture_output=True, text=True).stdout)
    return 0


if __name__ == "__main__":
    sys.exit(main())

